INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66064811', 66064811, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'KONSULTAN JUNIOR PENYUSUNAN KAJIAN PENGUATAN MANAJEMEN TALENTA NASIONAL (MTN) BIDANG OLAHRAGA PADA SEKRETARIAT MANAJEMEN TALENTA NASIONAL TAHUN 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99996000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 Bulan', 'a. Mengumpulkan data dan informasi terkait Desain Besar Manajemen Talenta Nasional; b. Mengoordinasikan pelaksanaan kegiatan, memastikan tujuan dan target tercapai sesuai jadwal yang ditentukan; c. Melakukan pemetaan permasalahan dan identifikasi kebutuhan data dan informasi terkait kebijakan/program/kegiatan yang berkaitan dengan kebijakan dan pelaksanaan MTN olahraga engan; d. Melaksanakan focus group discussion (FGD) baik di tingkat pusat maupun daerah melalui mekanisme luring, daring maupun hybrid (luring dan daring); e. Melakukan studi kasus di tingkat daerah untuk melakukan pendalaman data dan informasi mengenai kebijakan dan pelaksanaan MTN olahraga; f. Mengidentifikasi permasalahan dan kendala, faktor keberhasilan, serta risiko atau tantangan yang dihadapi dalam kebijakan dan pelaksanaan MTN olahraga; g. Menyusun rekomendasi sebagai bahan untuk perumusan dan perbaikan untuk rencana pembangunan selanjutnyA', 'a. Pendidikan minimal S2 dalam Ilmu Keolahragaan/Ilmu Olahraga/Ilmu Kesehatan Olahraga atau jurusan lain yang relevan dengan IPK minimal 3,25 (dari skala 4,00) dan akreditasi minimal B; b. Memiliki pengalaman kerja minimal 2 (dua) tahun dibidang yang sama; c. Memiliki kemampuan dalam pengumpulan, pengolahan, analisis data serta menulis laporan; d. Memiliki inisiatif untuk mempelajari isu-isu terkini, mengidentifikasi kebutuhan pengumpulan data, serta berkoordinasi dengan berbagai pihak terkait untuk mempercepat pencapaian output; e. Memiliki inisiatif, cekatan, kemauan belajar, komunikatif, dan dapat bekerja mandiri: f. Tidak berstatus sebagai ASN (PNS/TNI/Polri/). g. Sudah memiliki akun LPSE dan/atau memiliki NIB Perorangan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2540892);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66065024', 66065024, 'analyze_legacy', 'Provinsi Sulawesi Tengah', 'provinsi', 'Dinas Perpustakaan dan Kearsipan Provinsi Sulawesi Tengah', 'Belanja Alat/Bahan untuk Kegiatan Kantor-Alat Tulis Kantor', 'Jasa Lainnya', 'E-Purchasing', 'Sulawesi Tengah, Palu (Kota)', 696000, 'April 2026', 'APBD', 1, 1, '1 Paket', 'Spanduk; Penggandaan; Jilid Biasa', 'Spanduk; Foto copy hitam putih; Jilid Biasa', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2540893);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66064689', 66064689, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'KONSULTAN JUNIOR PENYUSUNAN KAJIAN DISEMINASI DESAIN BESAR MANAJEMEN TALENTA NASIONAL (MTN) PADA SEKRETARIAT MANAJEMEN TALENTA NASIONAL TAHUN 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99996000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 Bulan', 'a. Menyusun dokumen Perjanjian Kerjasama (PKS) dan Perjanjian Kerahasiaan (NDA) tentang Integrasi Data Talenta Nasional b. Menyusun panduan kerangka pelaksanaan diseminasi Desain Besar Manajemen Talenta Nasional, publikasi dan penyajian informasi terkait MTN di sosial media dan platform digital, pelaksanaan kegiatan dan rencana pendanaan dan kerjasama sinergi lintas stakeholder Sekretariat MTN dalam mendukung program dan kegiatan Manajemen Talenta Nasional; c. Menyusun analisis pemetaan dan identifikasi mitra strategis yang akan menjadi rekomendasi mitra dalam mendukung program dan kegiatan Manajemen Talenta Nasional; d. Menyusun laporan pelaksanaan dan pembelajaran pelaksanaan diseminasi dan Kemitraan Strategis Desain Besar Manajemen Talenta Nasional; e. Menyusun dokumen Rekomendasi dan tindak lanjut pelaksanaan diseminasi dan Kemitraan Strategis Desain Besar Manajemen Talenta Nasional;', 'a. Pendidikan minimal S1 dalam bidang/jurusan desain komunikasi visual / bidang/jurusan ilmu komunikasi atau bidang yang relevan lainnya; b. IPK minimal 3,25 (dari skala 4,00); c. Memiliki pengalaman kerja minimal 2 (dua) tahun di bidang yang sama; d. Memiliki pengalaman dalam kegiatan diseminasi progam/kegiatan dan kerjasama dengan mitra; e. Memiliki kemampuan Bahasa Inggris yang baik (pasif); f. Memiliki inisiatif, cekatan, kemauan belajar, komunikatif, dan dapat bekerja mandiri: g. Tidak berstatus sebagai ASN (PNS/TNI/Polri/); h. Sudah memiliki akun LPSE dan/atau memiliki NIB Perorangan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2540894);
