INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66065053', 66065053, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'KONSULTAN JUNIOR PENYUSUNAN KAJIAN PENGUATAN MANAJEMEN TALENTA NASIONAL (MTN) BIDANG RISET DAN INOVASI TAHUN 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99996000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 Bulan', 'a. Mengumpulkan data dan informasi terkait Desain Besar Manajemen Talenta Nasional; b. Mengoordinasikan pelaksanaan kegiatan, memastikan tujuan dan target tercapai sesuai jadwal yang ditentukan; c. Melakukan pemetaan permasalahan dan identifikasi kebutuhan data dan informasi terkait kebijakan/program/kegiatan yang berkaitan dengan kebijakan dan pelaksanaan Manajemen Talenta Nasional Bidang Riset dan Inovasi serta dapat berkoordinasi dengan 17 (tujuh belas) KL Gugus Kerja maupun Pemangku Kepentingan lainnya untuk memperoleh data dimaksud; d. Melaksanakan focus group discussion (FGD) baik di tingkat pusat maupun daerah melalui mekansime luring, daring maupun hybrid (luring dan daring); e. Melakukan studi kasus di tingkat daerah untuk melakukan pendalaman data dan informasi mengenai kebijakan dan pelaksanaan Manajemen Talenta Bidang Riset dan Inovasi;', 'a. Pendidikan minimal S1 dalam bidang/jurusan manajemen pendidikan/perencanaan atau bidang/jurusan relevan lainnya; b. IPK minimal 3,25 (dari skala 4,00); c. Memiliki pengalaman kerja minimal 2 (dua) tahun di bidang yang sama; d. Memiliki kemampuan dalam pengumpulan, pengolahan, analisis data serta menulis laporan; e. Memiliki kemampuan Bahasa Inggris yang baik (pasif); f. Memiliki inisiatif, cekatan, kemauan belajar, komunikatif, dan dapat bekerja mandiri: g. Tidak berstatus sebagai ASN (PNS/TNI/Polri/). h. Sudah memiliki akun LPSE dan/atau memiliki NIB Perorangan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2540903);
