INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66064877', 66064877, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'KONSULTAN JUNIOR PENYUSUNAN KAJIAN PENGUATAN MANAJEMEN TALENTA NASIONAL (MTN) BIDANG SENI BUDAYA PADA SEKRETARIAT MANAJEMEN TALENTA NASIONAL TAHUN 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99996000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 Bulan', '1. Mengumpulkan data dan informasi terkait Desain Besar Manajemen Talenta Nasional; 2. Mengoordinasikan pelaksanaan kegiatan, memastikan tujuan dan target tercapai sesuai jadwal yang ditentukan; 3. Melakukan pemetaan permasalahan dan identifikasi kebutuhan data dan informasi terkait kebijakan/program/kegiatan yang berkaitan dengan kebijakan dan pelaksanaan MTN olahraga dapat berkoordinasi dengan 17 (tujuh belas) KL Gugus Kerja maupun Pemangku Kepentingan lainnya untuk memperoleh data dimaksud; 4. Melaksanakan focus group discussion (FGD) baik di tingkat pusat maupun daerah melalui mekanisme luring, daring maupun hybrid (luring dan daring); 5. Melakukan studi kasus di tingkat daerah untuk melakukan pendalaman data dan informasi mengenai kebijakan dan pelaksanaan MTN Seni Budaya; 6. Mengidentifikasi permasalahan dan kendala, faktor keberhasilan, serta risiko atau tantangan yang dihadapi dalam kebijakan dan pelaksanaan MTN Seni Budaya;', '1. Bukan ASN atau anggota TNI/POLRI; 2. Pendidikan S2 jurusan Pendidikan Sosiologi atau jurusan yang relevan di perguruan tinggi dengan akreditasi minimal B 3. IPK minimal 3,50 (dari skala 4,00); 4. Memiliki pengalaman kerja minimal 2 (dua) tahun dibidang yang sama; 5. Memiliki kemampuan dalam mengolah data, menyajikan informasi, dan analisis hasil; 6. Memiliki inisiatif untuk mempelajari isu-isu terkini, mengidentifikasi kebutuhan pengumpulan data, serta berkoordinasi dengan berbagai pihak terkait untuk mempercepat pencapaian output; 7. Mempunyai pengalaman organisasi (menjadi nilai tambah); 8. Memiliki motivasi kerja dan kemauan belajar yang tinggi; dan 9. Menguasai infografis (menjadi nilai tambah). 10. Sudah memiliki akun LPSE dan/atau memiliki NIB Perorangan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2541027);
