INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66066635', 66066635, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Tenaga Ahli Penyusunan dan Evaluasi pelaksanaan SOP Kementerian PPN/Bappenas', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 90000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '1. Mendukung penyusunan dan penyempurnaan SOP (to-be). Mendukung tim Kementerian PPN/Bappenas dalam menyusun dan/atau menyempurnakan SOP Administrasi Pemerintah lingkup Kementerian PPN/Bappenas agar selaras dengan tugas dan fungsi unit kerja, kebutuhan organisasi, serta ketentuan PermenPANRB Nomor 35 Tahun 2012. 2. Mendukung evaluasi pelaksanaan SOP (to-be). Berkolaborasi dengan tim Kementerian PPN/Bappenas dalam melakukan evaluasi terhadap pelaksanaan SOP yang telah berlaku dan disempurnakan, termasuk penilaian kesesuaian SOP dengan praktik kerja aktual, kejelasan alur proses, serta tingkat kepatuhan dan kemudahan implementasi. 3. Mendukung monitoring implementasi SOP . Berkolaborasi dengan tim Kementerian PPN/Bappenas dalam melakukan monitoring atas pelaksanaan SOP, termasuk identifikasi permasalahan, hambatan, dan potensi perbaikan dalam pelaksanaannya. 4. Menyusun rekomendasi perbaikan dan penguatan implementasi SOP. Memberikan rekomendasi berbasis hasil evaluasi dan monitoring untuk penyempurnaan SOP serta penguatan penerapan SOP secara berkelanjutan di lingkungan Kementerian PPN/Bappenas.', 'Penyempurnaan dan penyusunan SOP Probis to-be', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2541388);
