INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66105407', 66105407, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'PENGADAAN JASA KONSULTAN PENYUSUNAN KAJIAN PERENCANAAN WILAYAH DAN KOTA PADA KEGIATAN KOORDINASI PENYUSUNAN KEBIJAKAN TERKAIT KETERPADUAN DAN TATA KELOLA INFRASTRUKTUR DAN PEMBANGUNAN BERKELANJUTAN BIDANG INFRASTRUKTUR STRATEGIS', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 79475000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1', '1. Melakukan analisis rekomendasi kebijakan aturan turunan Perpres RIPKA Jakarta Mencakup penyusunan analisis rekomendasi kebijakan untuk aturan turunan Perpres RIPKA Jakarta, yang dirumuskan berdasarkan pendalaman amanat Perpres serta temuan empiris dari kunjungan lapangan dan FGD dengan kementerian/lembaga serta pemerintah daerah dalam Kawasan Aglomerasi Jakarta. 2. Menyusun peta tematik dan basis data spasial yang diperlukan dalam proses pelaksanaan kegiatan Mencakup penyusunan peta tematik dan pengembangan basis data spasial yang diperlukan untuk mendukung proses pelaksanaan kegiatan terkait implementasi Perpres RIPKA Jakarta. 3. Menyusun laporan bulanan/berkala yang menggambarkan progres pelaksanaan kegiatan, temuan, serta kendala yang dihadapi', '1. Pendidikan minimal S1 Jurusan Perencanaan Wilayah dan Kota; 2. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta (dibuktikan dengan kontrak/referensi); 3. Memiliki pengalaman kerja umum minimum 4 (empat) tahun di bidang sejenis yang dibuktikan melalui pengalaman kerja yang tertera dalam CV; 4. Memiliki pengalaman menggunakan perangkat lunak Geographic Information System (GIS); 5. Mampu bekerja dalam tim dan bersedia ditugaskan ke berbagai lokasi untuk keperluan pekerjaan; 6. Memiliki pengalaman dalam pekerjaan pengelolaan kawasan metropolitan/aglomerasi dan pernah menyusun kebijakan terkait pengelolaan kawasan metropolitan/aglomerasi 7. Memiliki pengalaman kerja dengan nilai pekerjaan sejenis tertinggi dalam kurun waktu 4 (empat) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai total HPS/Pagu Anggaran.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2542118);
