INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66067585', 66067585, 'analyze_legacy', 'Kementerian Perindustrian', 'central', 'Direktorat Jenderal Industri Kecil Menengah dan Aneka', 'Temu Bisnis IKM Kerajinan', 'Jasa Lainnya', 'Pengadaan Langsung', 'DI Yogyakarta, Yogyakarta (Kota)', 168233000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Kegiatan ini meliputi rangkaian program meliputi: -Pameran Produk : Display produk adalah komponen penting dari temu bisnis Kerajinan di mana perusahaan Kerajinan memamerkan produk-produk mereka kepada para peserta. Ini memberikan kesempatan bagi produsen Kerajinan untuk memamerkan produk baru, terbaik, atau unik mereka kepada distributor, pengecer, dan pemangku kepentingan lainnya. -Sesi Networking : Temu bisnis Kerajinan sering kali mencakup sesi jaringan atau pertemuan antara peserta. Ini adalah waktu yang baik untuk berinteraksi secara informal, bertukar kartu nama, dan membangun hubungan bisnis yang berpotensi. -Sesi Presentasi : Sesi presentasi atau seminar dapat diadakan untuk membahas tren terbaru dalam industri Kerajinan, inovasi produk, teknologi terbaru, atau isu-isu regulasi. Para ahli di industri ini biasanya memberikan presentasi dan berbagi pengetahuan mereka. -Sesi One-on-One : Banyak temu bisnis kerajinan menyediakan kesempatan untuk pertemuan satu lawan satu antara produsen kerajinan, distributor, dan pemasok bahan baku. Ini memungkinkan diskusi yang lebih mendalam tentang peluang kemitraan dan negosiasi bisnis.', 'Temu Bisnis IKM Kerajinan Pelaksana yang diperlukan untuk melaksanakan pekerjaan ini adalah Ketua Tim (Team Leader) sebanyak 1 orang dengan persyaratan: -Memiliki Sertifikat Kompetensi masih berlaku; -Pendidikan minimal D IV/ Sarjana yang dibuktikan dengan ijazah; -Memiliki pengalaman di bidang event organizer minimal 10 kegiatan dalam 3 tahun terakhir dibuktikan dengan Surat Referensi Perusahaan; -Melampirkan Curriculum Vitae, copy KTP, NPWP dan mampu berkomunikasi dengan baik. Tugas Ketua Tim antara lain: -Mengkoordinasikan pelaksanaan pekerjaan pada seluruh Direktorat mulai dari perencanaan, koordinasi, pelaksanaan sampai pelaporan; -Mengkoordinasikan pelaksanan Tim (Tenaga Administrasi dan Tenaga Teknis) dengan melampirkan pembagian kerja dari masing – masing Tim; -Memastikan bahwa pekerjaan terlaksana sesuai dengan rencana serta memenuhi persyaratan yang diinginkan pengguna jasa. Tenaga Administrasi dan Teknis sebanyak 2 (dua) orang dengan persyaratan: -Pendidikan minimal D3 yang dibuktikan dengan ijazah; -Memiliki pengalaman di bidang event organizer minimal 5 kegiatan dalam 3 tahun terakhir dibuktikan dengan Surat Referensi Perusahaan; -Melampirkan Curriculum Vitae, copy KTP, dan mampu berkomunikasi dengan baik. Tenaga Administrasi dan Teknis bertugas membantu Ketua Tim (Team Leader) dalam pelaksanaan kegiatan pada seluruh Direktorat agar berjalan dengan baik dan lancar.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2542952);
