INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66106435', 66106435, 'analyze_legacy', 'Kab. Sambas', 'kabkota', 'DINAS PEKERJAAN UMUM DAN PENATAAN RUANG', 'Fasilitasi Penetapan Rancangan Peraturan Daerah tentang RTRW Kabupaten Sambas', 'Jasa Konsultansi', 'Seleksi', 'Kalimantan Barat, Sambas (Kab.)', 420000000, 'March 2026', 'APBD', 1, 1, 'Paket', 'Pelaksanaan teknis pekerjaan berdasar atas Permendagri Nomor 13 Tahun 2016, Permen ATR Nomor 11 Tahun 2021, dan Permen ATR Nomor 14 Tahun 2021. Adapun lingkup pekerjaan terdiri atas 3 (tiga) tahap berikut: 1. Tahap Persiapan, di antaranya: a. Melakukan asistensi/koordinasi ke Dinas PUPR Kabupaten dan/atau Forum Penataan Ruang Daerah (FPRD) Kabupaten untuk memperoleh data/informasi awal dan arahan-arahan pokok pelaksanaan pekerjaan; b. Melakukan kajian awal terhadap data dasar, standar teknis, studi terdahulu, dan dasar hukum khususnya Lampiran VI.5 Permen ATR Nomor 11 Tahun 2021 tentang Kelengkapan Dokumen Untuk Keterangan Kesesuaian Substansi; c. Menyusun rencana kerja rinci, metodologi pendekatan, daftar kebutuhan data/informasi/peta, dan perangkat survei; 2. Tahap Asistensi/Konsultasi ke Ditjen Tata Ruang, Kementerian ATR, di antaranya: a. Mendampingi Dinas PUPR Kabupaten dalam hal asistensi/konsultasi ke Ditjen Tata Ruang; b. Melakukan penyesuaian dan pemutakhiran Ranperda dan Peta RTRWK sesuai koreksi/masukan Ditjen Tata Ruang dan ketentuan peraturan perundang-undangan; 3. Tahap Asistensi/Konsultasi ke Biro Hukum Setda Provinsi dan Ditjen Bina Pembangunan Daerah, Kementerian Dalam Negeri, di antaranya: a. Mendampingi Dinas PUPR Kabupaten dalam hal asistensi/konsultasi ke Biro Hukum Setda Provinsi dan Ditjen Bina Pembangunan Daerah; b. Melakukan penyesuaian dan pemutakhiran Ranperda dan Peta RTRWK sesuai koreksi/masukan Biro Hukum Setda Provinsi dan Ditjen Bina Pembangunan Daerah serta ketentuan peraturan perundang-undangan.', 'Spesifikasi Pekerjaan, diantaranya: a. Peraturan Pemerintah Nomor 21 Tahun 2021 tentang Penyelenggaraan Penataan Ruang; b. Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2016 tentang Evaluasi Rancangan Peraturan Daerah tentang Rencana Tata Ruang Daerah; c. Peraturan Menteri Dalam Negeri Nomor 120 Tahun 2018 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 80 Tahun 2015 tentang Pembentukan Produk Hukum Daerah; d. Peraturan Menteri Agraria dan Tata Ruang / Kepala Badan Pertanahan Nasional Nomor 11 Tahun 2021 tentang Tata Cara Penyusunan, Peninjauan Kembali, Revisi, dan Penerbitan Persetujuan Substansi Rencana Tata Ruang Wilayah Provinsi, Kabupaten, Kota, dan Rencana Detail Tata Ruang; e. Peraturan Menteri Agraria dan Tata Ruang / Kepala Badan Pertanahan Nasional Nomor 14 Tahun 2021 tentang Pedoman Penyusunan Basis Data dan Penyajian Peta Rencana Tata Ruang Wilayah Provinsi, Kabupaten, dan Kota serta Peta Rencana Detail Tata Ruang; f. Peraturan Menteri Agraria dan Tata Ruang / Kepala Badan Pertanahan Nasional Nomor 5 Tahun 2022 tentang Tata Cara Pengintegrasian Kajian Lingkungan Hidup Strategis Dalam Penyusunan Rencana Tata Ruang; g. Keputusan Menteri Dalam Negeri Nomor 300.2.2-2430 Tahun 2025 tentang Perubahan Atas Keputusan Menteri Dalam Negeri Nomor 300.2.2-2138 Tahun 2025 tentang Pemberian dan Pemutakhiran Kode, Data Wilayah Administrasi Pemerintahan, dan Pulau; h. Keputusan Menteri Dalam Negeri Nomor 900.1-2850 Tahun 2025 tentang Perubahan Ketiga atas Keputusan Menteri Dalam Negeri Nomor 050-5889 Tahun 2021 tentang Hasil Verifikasi, Validasi dan Inventarisasi Pemutakhiran Klasifikasi, Kodefikasi dan Nomenklatur Perencanaan Pembangunan dan Keuangan Daerah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2543433);
