INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66067432', 66067432, 'analyze_legacy', 'Provinsi Jawa Barat', 'provinsi', 'Dinas Bina Marga dan Penataan Ruang', 'Kajian Pengendalian Perizinan Perkebunan', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Barat, Bandung (Kota)', 33683255, 'January 2026', 'APBD', 1, 1, '1 Pekerjaan', 'Kegiatan ini dimaksudkan untuk memastikan bahwa setiap pemegang izin usaha perkebunan menjalankan aktivitasnya sesuai dengan fungsi ruang dan perizinan yang diberikan, serta mencegah terjadinya penyimpangan penggunaan lahan secara ilegal yang dapat memicu terjadinya bencana. Adapun tujuan kegiatan ini adalah untuk menilai dampak alih fungsi lahan perkebunan terhadap penurunan daya dukung dan daya tampung lingkungan, yang memicu kerentanan bencana hidrogeologi di Provinsi Jawa Barat.', 'Ruang lingkup kegiatan Pengendalian Perizinan Perkebunan, yaitu: 1. Melakukan inventarisasi data perizinan yang diterbitkan melalui sistem OSS RBA di wilayah kajian; 2. Melakukan telaahan kesesuaian dokumen perizinan dengan RTR baik RTRW Provinsi, RTRW Kabupaten/Kota dan/atau RDTR Kabupaten/Kota; 3. Melakukan identifkasi lokasi terindikasi alih fungsi lahan di kawasan perkebunan; 4. Menyusun tipologi prioritas pengendalian kegiatan pemanfaatan ruang di kawasan perkebunan; dan 5. Merumuskan rekomendasi kebijakan terkait langkah pengendalian terhadap kegiatan pemanfaatan ruang di kawasan perkebunan.', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 2543660);
