INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66067664', 66067664, 'analyze_legacy', 'Provinsi Jawa Barat', 'provinsi', 'Dinas Bina Marga dan Penataan Ruang', 'Kajian Pengendalian Perizinan Perumahan', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Barat, Bandung (Kota)', 33683255, 'January 2026', 'APBD', 1, 1, '1 Pekerjaan', 'Kegiatan ini dimaksudkan untuk melakukan evaluasi, pengawasan, dan pengendalian perizinan perumahan untuk memberikan gambaran mengenai tingkat kepatuhan dan kesesuaian rencana tata ruang dan pemenuhan persyaratan teknis terhadap kegiatan perumahan. Adapun tujuan kegiatan ini adalah untuk memastikan kepatuhan kegiatan perumahan sesuai dengan Rencana Tata Ruang (RTR) yang telah ditetapkan serta upaya mitigasi kawasan risiko bencana yang sering kali tidak menjadi faktor yang diperhatikan dalam aktivitas pembangunan perumahan.', 'Ruang lingkup kegiatan Pengendalian Perizinan Perumahan, yaitu: 1. Melakukan inventarisasi data perizinan yang diterbitkan melalui sistem OSS RBA di wilayah kajian; 2. Melakukan telaahan kesesuaian dokumen perizinan dengan RTR baik RTRW Provinsi, RTRW Kabupaten/Kota dan/atau RDTR Kabupaten/Kota; 3. Melakukan identifkasi lokasi perumahan eksisting yang berada pada kawasan rawan bencana; 4. Menyusun tipologi prioritas pengendalian kegiatan perumahan di kawasan rawan bencana; dan 5. Merumuskan rekomendasi kebijakan terkait langkah pengendalian pemanfaatan ruang terhadap kegiatan perumahan yang teridentifikasi memiliki risiko bencana.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2543720);
