INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66067783', 66067783, 'analyze_legacy', 'Provinsi Jawa Barat', 'provinsi', 'Dinas Bina Marga dan Penataan Ruang', 'Kajian Risiko Bencana pada Kawasan Budidaya', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Barat, Bandung (Kota)', 33683255, 'January 2026', 'APBD', 1, 1, '1 Pekerjaan', 'Kegiatan ini dimaksudkan untuk melakukan identifikasi dan analisis mengenai potensi bahaya, tingkat kerentanan, dan kapasitas wilayah pada kawasan budidaya meliputi kesiapan kelembagaan, ketersediaan sarana prasarana mitigasi, dan ketangguhan masyarakat dalam menghadapi bencana. Adapun tujuan kegiatan ini adalah untuk memetakan jenis dan sebaran potensi bencana yang berada pada kawasan budidaya.', 'Ruang lingkup kegiatan Kajian Risiko Bencana pada Kawasan Budidaya, yaitu: 1. Melakukan identifikasi jenis ancaman bencana yang berpotensi terjadi di kawasan budidaya; 2. Melakukan analisis kerentanan kawasan budidaya terhadap bencana, meliputi aspek fisik, sosial, dan ekonomi; 3. Melakukan analisis kapasitas dan kesiapsiagaan bencana; 4. Melakukan analisis keterkaitan risiko bencana terhadap kesesuaian rencana tata ruang dan alih fungsi lahan; 5. Melakukan pemetaan risiko bencana pada kawasan budidaya; 6. Merumuskan rekomendasi teknis pengendalian pemanfaatan ruang pada zona risiko bencana; dan 7. Menyusun rekomendasi penguatan kapasitas masyarakat di kawasan budidaya.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2544335);
