INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66154759', 66154759, 'analyze_legacy', 'Kementerian Kelautan Dan Perikanan', 'central', 'PELABUHAN PERIKANAN NUSANTARA PENGAMBENGAN', 'PJLP jasa sopir', 'Jasa Lainnya', 'Pengadaan Langsung', 'Bali, Jembrana (Kab.)', 98280000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, PAKET, @ 116000000 )', '1. Outsourcing jasa sopir (2 orang) ( 1, PAKET, @ 116000000 );', 'Berikut adalah spesifikasi pekerjaan (Kerangka Acuan Kerja) untuk Jasa Sopir/Driver, yang biasanya digunakan dalam kontrak pengadaan jasa tenaga kerja (Outsourcing) di instansi pemerintah atau perusahaan: 1. Kualifikasi Personel Pendidikan: Minimal SMA atau sederajat. Dokumen Wajib: Memiliki SIM A atau SIM B1 (masih berlaku) sesuai dengan jenis kendaraan yang dioperasikan. Pengalaman: Memiliki pengalaman mengemudi minimal 2–3 tahun. Kesehatan: Sehat jasmani dan rohani, tidak memiliki gangguan penglihatan yang berat, serta bebas dari narkoba. 2. Lingkup Pekerjaan (Job Desk) Pelayanan Mengemudi: Mengantarkan pimpinan atau staf dalam menjalankan tugas kedinasan dengan aman dan tepat waktu. Pemeliharaan Kendaraan: * Mengecek rutin kondisi mesin, oli, air radiator, tekanan ban, dan fungsi rem. Menjaga kebersihan eksterior dan interior kendaraan setiap hari. Administrasi Kendaraan: * Mengisi buku log harian (tujuan perjalanan, kilometer awal/akhir, dan konsumsi BBM). Melaporkan/mengingatkan jadwal servis rutin dan masa berlaku pajak STNK. Keamanan: Memastikan kendaraan diparkir di tempat yang aman dan terkunci dengan benar. 3. Etika dan Perilaku Disiplin: Hadir tepat waktu sesuai jam kerja atau jadwal penugasan khusus (lembur). Penampilan: Berpakaian rapi, sopan, dan menggunakan seragam (jika disediakan). Komunikasi: Memiliki sikap ramah, menjaga rahasia instansi/pimpinan, dan dilarang merokok di dalam kendaraan. Kepatuhan: Menaati seluruh peraturan lalu lintas yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2548090);
