INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66154425', 66154425, 'analyze_legacy', 'Kementerian Kelautan Dan Perikanan', 'central', 'PELABUHAN PERIKANAN NUSANTARA PENGAMBENGAN', 'KEBUTUHAN SEHARI-HARI PERKANTORAN', 'Barang', 'Pengadaan Langsung', 'Bali, Jembrana (Kab.)', 167666000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Belanja Keperluan Perkantoran; 2. Belanja Barang Operasional Lainnya; 3. Belanja Barang Persediaan Barang Konsumsi;', '1. Belanja Keperluan Perkantoran Fokus: Barang habis pakai yang mendukung administrasi dan kebersihan kantor harian. Kertas & Pencetakan: Kertas HVS (A4/F4) 80gr, tinta/toner printer (hitam & warna), pita printer (jika ada). Alat Tulis & Kantor: Map folder, ordner, staples, penjepit kertas (paper clip), penggaris, gunting, dan pelubang kertas. Kebersihan & Sanitasi: Cairan pembersih lantai, sabun cuci tangan, tisu (toilet & meja), semprotan pengharum ruangan, kantong sampah, dan alat kebersihan (sapu/pel). Lain-lain: Materai (10.000), baterai untuk jam dinding/remote, dan perlengkapan P3K ringan. 2. Belanja Barang Operasional Lainnya Fokus: Barang atau jasa yang mendukung aktivitas di luar administrasi rutin untuk kelancaran organisasi. Sarana Pendukung: Pengadaan spanduk/banner kegiatan, umbul-umbul, atau papan informasi. Biaya Langganan: Pembayaran langganan internet, pulsa data/paket data untuk modem operasional, atau biaya langganan aplikasi (misal: Zoom, Canva, Adobe). Suku Cadang Ringan: Penggantian lampu ruangan yang mati, pengisian ulang APAR (Alat Pemadam Api Ringan), atau servis ringan AC kantor. Seragam/Atribut: Jika ada pengadaan kaos lapangan atau identitas panitia/petugas operasional tertentu. 3. Belanja Barang Persediaan Barang Konsumsi Fokus: Bahan makanan atau minuman yang disimpan sebagai stok untuk tamu atau kebutuhan harian. Minuman Utama: Penyediaan air mineral galon atau botol plastik ukuran 330ml/600ml. Bahan Minuman: Stok kopi bubuk, teh celup, gula pasir, dan krimer/susu kental manis untuk pantry. Makanan Ringan (Stok): Biskuit atau camilan kering yang disediakan di ruang tamu atau ruang rapat sebagai cadangan. Perlengkapan Penyajian: Gelas plastik sekali pakai, sendok plastik, atau tisu makan khusus pantry.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2548645);
